mapper.select:
SELECT t.id, t.name, t.article_count FROM ( SELECT c.id, c.name, COUNT(a.id) AS article_count FROM tb_category c LEFT JOIN tb_article a ON a.category_id = c.id
AND c.name LIKE CONCAT('%', #{name}, '%')
GROUP BY c.id, c.name ) t
AND t.article_count >= #{minCount}
AND t.article_count <= #{maxCount}
ORDER BY t.article_count DESC, t.id ASC

SELECT t.category_id, t.id, t.title, t.view_count FROM ( SELECT a.category_id, a.id, a.title, a.view_count, ROW_NUMBER() OVER ( PARTITION BY a.category_id ORDER BY a.view_count DESC, a.id ASC ) AS rn FROM tb_article a WHERE a.status = 1 AND a.category_id IN
#{categoryId}
) t WHERE t.rn <= #{limit} ORDER BY t.category_id ASC, t.rn ASC
